export type NodeType = 'router' | 'switch' | 'pc' | 'cloud' | 'firewall' | 'server' | 'host' | 'bridge'
export type NodeStatus = 'stopped' | 'running' | 'suspended'
export type LinkType = 'ethernet' | 'serial'
export type SwitchFamily =
    // Juniper
    | 'QFX' | 'EX' | 'MX' | 'PTX' | 'PTX-EVO' | 'ACX' | 'SRX'
    // Cisco
    | 'Catalyst' | 'Nexus' | 'ISR' | 'ASR'
    // Arista
    | '7050X' | '7060X' | '7280R' | '7500R' | '720XP'
    // Nokia
    | '7220-IXR' | '7250-IXR' | '7750-SR'
    // SONiC
    | 'Edgecore' | 'Celestica' | 'SONiC-Dell'
    // HPE
    | 'Aruba-CX' | 'FlexNetwork'
    // Huawei
    | 'CloudEngine' | 'NetEngine' | 'S-Series'
    // Dell
    | 'S-PowerSwitch' | 'Z-PowerSwitch' | 'N-PowerSwitch'
    // MikroTik
    | 'CRS' | 'CCR' | 'RB'
    // Extreme
    | 'ExtremeSwitching' | 'SLX' | 'VSP'

// ── Live topology status types ──────────────────────────────────────────────
export type BgpSessionState = 'established' | 'active' | 'connect' | 'openconfirm' | 'opensent' | 'idle' | 'unknown'

export interface BgpNeighborEntry {
    neighborIp: string
    state: BgpSessionState
    asn: number
    prefixCount: number
}

export interface ContainerLiveStatus {
    containerName: string
    state: string
    bgpNeighbors: BgpNeighborEntry[]
    srEnabled?: boolean         // SR-MPLS status (polled on supported vendors)
    srLabelsCount?: number      // SR-MPLS label binding count
    vniActive?: number          // Active VXLAN VNI count
}

export interface LiveStatusPollResult {
    ok: boolean
    message?: string
    containers: ContainerLiveStatus[]
}

// ── Traffic Flow types ─────────────────────────────────────────────────────────

export interface TrafficFlow {
    id: string
    name: string
    sourceNodeId: string
    destNodeId: string
    protocol?: 'TCP' | 'UDP' | 'ICMP' | 'Any'
    port?: number
    color: string
    enabled: boolean
}

export interface ComputedFlowPath {
    flowId: string
    pathIndex: number
    linkIds: string[]
    nodeIds: string[]
    broken: boolean
    rerouted: boolean
}

// ─── Port ─────────────────────────────────────────────────────────────────────

export type PortSpeed = '10M' | '100M' | '1G' | '2.5G' | '5G' | '10G' | '25G' | '40G' | '50G' | '100G' | '200G' | '400G' | '800G'
export type PortVlanMode = 'access' | 'trunk'

export interface VlanDefinition {
    id: number      // 1–4094
    name: string    // e.g. "MGMT", "DATA"
}

export interface NodePort {
    id: string
    label: string           // e.g. "e0/0", "Gi0/1"
    ipAddress?: string      // IPv4/CIDR, e.g. "192.168.1.1/24"
    ipv6Address?: string    // IPv6/prefix, e.g. "fd00::1/127"
    description?: string
    enabled: boolean
    speed?: PortSpeed       // interface speed — used in startup config & display
    vlan?: number           // access VLAN ID (1–4094)
    vlanMode?: PortVlanMode       // undefined = 'access'
    trunkNativeVlan?: number      // native (untagged) VLAN for trunk mode
    trunkAllowedVlans?: string    // e.g. "100,200,300-400"
}

// ─── Node ─────────────────────────────────────────────────────────────────────

export interface TopologyNode {
    id: string
    type: NodeType
    label: string
    x: number
    y: number
    status: NodeStatus
    ports: NodePort[]

    // Phase 2 config fields
    description?: string
    ram?: number            // MB
    image?: string          // device image / template name
    startupConfig?: string  // multi-line startup config text
    configSource?: 'generated' | 'pulled' | 'manual'  // track config origin to prevent overwrite
    notes?: string

    // Real device mapping fields
    mgmtIp?: string
    sshPort?: number
    sshUsername?: string
    sshPassword?: string

    // Bastion / jump host for multi-hop SSH
    bastionHost?: string
    bastionPort?: number
    bastionUsername?: string
    bastionPassword?: string

    vendor?: string
    desiredPortCount?: number
    portSuffix?: string
    operatingSpeed?: PortSpeed
    model?: string
    switchFamily?: SwitchFamily
    vlans?: VlanDefinition[]      // node-level VLAN table
    serialNumber?: string
    sourceId?: string
    mapped?: boolean
    mappedBy?: 'hostname' | 'mgmtIp'
    loopbackIp?: string          // Loopback IP (e.g. "172.16.0.1/32"), separate from mgmtIp
    loopbackIpv6?: string        // IPv6 Loopback (e.g. "fd00::1/128"), separate from loopbackIp
    role?: NodeRole             // builder-assigned role tag (spine, leaf, etc.)
    asn?: number                // BGP autonomous system number
    ospfArea?: number           // OSPF area ID (0 = backbone)
    isisLevel?: 1 | 2 | 12     // IS-IS level (12 = L1/L2)
    nodeSid?: number            // SR-MPLS Node SID index (e.g. 1 → label 16001)
    srgbStart?: number          // SRGB start label (default 16000)
    srgbEnd?: number            // SRGB end label (default 23999)
    srv6Locator?: string        // SRv6 locator prefix (e.g. fc00:0:1::/48)
    mplsLdp?: boolean           // enable MPLS LDP on this node
    telemetryEnabled?: boolean  // gRPC/gNMI telemetry streaming

    /** Per-node overrides for the topology-wide staging defaults. Only the
     *  fields you want to override need to be set; everything else falls
     *  through to topology.staging. */
    staging?: DeviceStagingConfig

    // SNMP polling
    pollMethod?: 'ssh' | 'snmp'
    snmpVersion?: '2c' | '3'
    snmpCommunity?: string
    snmpPort?: number
    snmpAuthProtocol?: 'md5' | 'sha'
    snmpAuthPassword?: string
    snmpPrivProtocol?: 'des' | 'aes'
    snmpPrivPassword?: string

    // Multi-server deploy
    serverId?: string           // ID of the clab server this node is assigned to

    // Physical port (host interface) mapping
    hostInterface?: string      // physical NIC name on the clab server (e.g. "enp3s0")

    // Bridge node fields
    bridgeName?: string         // selected bridge name (e.g. "virbr0", "br-fabric")
    bridgeType?: 'linux' | 'libvirt' | 'ovs'  // bridge backend type

    // Visual sizing (optional — defaults to NODE_W/NODE_H or infraNw/infraNh for host/bridge)
    width?: number
    height?: number
}

// ─── Link ─────────────────────────────────────────────────────────────────────

export interface TopologyLink {
    id: string
    type: LinkType
    sourceNodeId: string
    sourcePortId: string
    targetNodeId: string
    targetPortId: string

    // Shape endpoints (optional — when one end is a rectangle shape instead of a node)
    sourceAnnotationId?: string
    targetAnnotationId?: string
    // Anchor offsets (fraction 0–1 of shape width/height, so they survive resizing)
    sourceAnchorX?: number
    sourceAnchorY?: number
    targetAnchorX?: number
    targetAnchorY?: number

    // Phase 2 link config
    bandwidth?: number      // Mbps; undefined = unlimited
    latency?: number        // ms
    packetLoss?: number     // % 0–100
    duplex?: 'full' | 'half'
    notes?: string
    status?: 'up' | 'down'
    bendOffset?: number     // perpendicular pixel offset for manual curve adjustment
    userLabel?: string      // DEPRECATED: single label (migrated to labels[])
    linkColor?: string      // custom stroke color
    linkDash?: string       // dash pattern: '' (solid), '6,4' (dashed), '2,3' (dotted)
    linkWidth?: number      // custom stroke width
    showArrow?: boolean     // show arrowhead at target end
    arrowStart?: boolean    // show arrowhead at source end
    routing?: 'straight' | 'orthogonal'  // path routing style
    sketched?: boolean      // sketched/hand-drawn style
    waypoints?: { x: number; y: number }[]  // intermediate points for custom routing
    labelFontSize?: number  // DEPRECATED (migrated to labels[])
    labelFontWeight?: 'normal' | 'bold'  // DEPRECATED
    labelColor?: string     // DEPRECATED
    labelOffsetX?: number   // DEPRECATED
    labelOffsetY?: number   // DEPRECATED
    labels?: LinkLabel[]    // multiple user-defined labels
}

export interface LinkLabel {
    id: string
    text: string
    t: number               // position along link: 0 = source, 0.5 = midpoint, 1 = target
    perpOffset: number      // perpendicular distance from the link line (+ = left, - = right)
    fontSize?: number       // px (default 11)
    fontWeight?: 'normal' | 'bold'
    color?: string          // text color
}

// ─── Annotation ───────────────────────────────────────────────────────────────

export type AnnotationType = 'text' | 'rectangle' | 'circle' | 'diamond' | 'triangle'
    | 'star' | 'hexagon' | 'parallelogram' | 'cylinder' | 'cloud' | 'arrow-right' | 'arrow-double' | 'line-h'
    | 'image'

export interface Annotation {
    id: string
    type?: AnnotationType       // default 'text' for backward compat
    x: number
    y: number
    text: string
    width: number
    height: number
    // Shape style (used by 'rectangle')
    fillColor?: string
    strokeColor?: string
    strokeWidth?: number
    opacity?: number
    cornerRadius?: number
    label?: string              // optional label shown inside shape
    // Zone / group
    rotation?: number           // degrees rotation (0-360)
    isZone?: boolean            // true = zone grouping rectangle
    zoneNodeIds?: string[]      // node IDs contained in the zone
    locked?: boolean            // locked shapes can't be moved, resized, or deleted
    // Image annotation
    imageData?: string          // base64 data URL for image annotations (e.g. "data:image/png;base64,...")
}

// ─── Device Staging (Day-0 onboarding config) ────────────────────────────────

/**
 * Foundational config applied BEFORE fabric protocols. Set fabric-wide
 * defaults on Topology.staging; per-node overrides go on TopologyNode.
 *
 * Each field is optional — emit nothing if undefined. Vendor-aware rendering
 * lives in services/vendor-config-builder.ts (renderStagingConfig).
 */
export interface DeviceStagingConfig {
    /** NTP / time sync */
    ntp?: {
        servers?: string[]              // ['10.0.0.1', 'pool.ntp.org']
        prefer?: string                 // hostname/IP to prefer
        timezone?: string               // 'UTC' / 'America/Los_Angeles' / 'PST8PDT'
        sourceInterface?: string        // optional source-interface name
    }

    /** SNMP read/trap config */
    snmp?: {
        version?: 'v2c' | 'v3'
        community?: string              // v2c read-only community
        contact?: string                // free-text
        location?: string
        trapTargets?: string[]          // trap server IPs
        // v3 user (when version === 'v3')
        v3User?: string
        v3AuthProtocol?: 'sha' | 'md5'
        v3AuthPassword?: string
        v3PrivProtocol?: 'aes' | 'des'
        v3PrivPassword?: string
    }

    /** LLDP enable + scope */
    lldp?: {
        enabled?: boolean               // default true on most vendors
        interfaces?: 'all' | string[]   // 'all' or specific iface list
    }

    /** Syslog forwarding */
    syslog?: {
        servers?: string[]
        severity?: 'emergencies' | 'alerts' | 'critical' | 'errors' | 'warnings' |
                   'notifications' | 'informational' | 'debugging'
    }

    /** DNS resolver */
    dns?: {
        servers?: string[]              // ['8.8.8.8', '1.1.1.1']
        searchDomain?: string           // 'lab.example.com'
    }

    /** Local users + optional TACACS */
    aaa?: {
        localUsers?: Array<{
            username: string
            password?: string           // plaintext — vendor-specific hashing in builder
            role?: 'admin' | 'read-only' | 'operator'
        }>
        tacacs?: {
            servers?: string[]
            sharedSecret?: string
        }
    }

    /** Banners */
    banner?: {
        login?: string                  // multi-line MOTD
        exec?: string
    }
}

// ─── Topology ─────────────────────────────────────────────────────────────────

export interface Topology {
    id: string
    name: string
    description?: string
    nodes: TopologyNode[]
    links: TopologyLink[]
    annotations?: Annotation[]
    createdAt: string
    updatedAt: string

    // Routing config generation hints (set by builder or template)
    underlayProtocol?: 'ebgp' | 'ibgp-rr' | 'ospf' | 'ospfv3' | 'isis'
    overlayEnabled?: boolean
    vniBase?: number             // default 10000; VNI = vniBase + vlanId
    irbEnabled?: boolean         // generate IRB interfaces for inter-VLAN routing (distributed gateway)
    irbGatewayBase?: string      // base gateway IP prefix, e.g. "192.168" → 192.168.<vlanId>.1/24
    macVrfEnabled?: boolean      // use MAC-VRF instances instead of default-switch EVI
    irbMode?: 'symmetric' | 'asymmetric'  // symmetric = L3 VNI + Type-5 VRF; asymmetric = all VLANs on all leaves
    oismEnabled?: boolean        // OISM: IGMP snooping, SMET routes, assisted replication
    telemetryEnabled?: boolean   // gRPC/gNMI telemetry streaming
    telemetryConfig?: TelemetryConfig  // detailed telemetry settings

    /** Day-0 staging defaults applied to every node (NTP, SNMP, LLDP, syslog,
     *  DNS, AAA users, banner). Per-node overrides live on TopologyNode.staging. */
    staging?: DeviceStagingConfig

    /** First-class IP-VRF / EVPN T5 routing-instance definitions. Lets a
     *  template (or an authored topology) describe per-VRF VNI, RD, RT and
     *  interconnect-stitching parameters that downstream config-gen can lower
     *  into Junos `ip-vrf { protocols evpn { interconnect { ... } } }` or
     *  equivalent stanzas on other vendors. Introduced for RLI 52387
     *  (Pure T5↔T5 EVPN-VXLAN seamless stitching). */
    vrfs?: VrfDefinition[]
}

/**
 * IP-VRF definition for EVPN-VXLAN T5 fabrics, with optional interconnect
 * stanza for seamless T5↔T5 stitching (RLI 52387 / draft-bess-evpn-prefix-
 * advertisement). One VRF can be applied to many member nodes; for N:1
 * stitching multiple DC-side VRFs map to the same interconnect VRF on the iGW.
 */
export interface VrfDefinition {
    /** Stable identifier within the topology/template. */
    id: string
    /** Display name, e.g. 'T5-VRF-A'. */
    name: string
    /** Instance type — currently only 'vrf' for IP-VRF; reserved for future. */
    instanceType: 'vrf'
    /** Routing VNI (L3 VNI) — e.g. 70104 on DC side, 80104 on interconnect. */
    routingVni: number
    /** Route distinguisher, e.g. '100.1.1.11:1'. */
    routeDistinguisher: string
    /** VRF target community, e.g. 'target:1:101'. */
    vrfTarget: string
    /** Indices into topology.nodes (or template.nodes) that participate
     *  in this VRF — i.e. nodes that host the IP-VRF routing instance. */
    memberNodes: number[]
    /** Subset of `memberNodes` that additionally carry the
     *  `protocols evpn { interconnect { ... } }` stanza (i.e. the iGWs that
     *  re-originate T5 routes onto the DCI). When omitted, the `interconnect`
     *  block — if present — is treated as applying to all `memberNodes`.
     *  Use this to distinguish the 1:1 case (one VRF shared across leaves +
     *  iGWs, but only iGWs re-originate) from N:1 (separate interco VRF
     *  whose every member is an iGW). */
    interconnectNodes?: number[]
    /** EVPN domain-id for D_PATH loop prevention (RLI 50205 + RLI 52387),
     *  e.g. '6500:1:evpn' or '6500:2:evpn-dci'. */
    domainId?: string
    /** Optional interconnect stanza — present on iGW-side VRFs that re-originate
     *  T5 routes onto the DCI fabric. When `mapsToVrfId` is set, that's the
     *  remote/interconnect VRF this one stitches into; for N:1, multiple
     *  DC-side VRFs share the same `mapsToVrfId`. */
    interconnect?: {
        routeDistinguisher?: string
        vrfTarget?: string
        routingVni?: number
        domainId?: string
        mapsToVrfId?: string
    }
    /** Chassis MAC used as the router-mac community on re-originated T5 NLRI. */
    chassisMac?: string
    /** Free-form description (subnet list, tenant role, fabric position). */
    description?: string
}

export interface TelemetryConfig {
    collectorIp: string          // e.g. '10.0.0.100'
    collectorPort: number        // e.g. 50051
    encoding: 'gpb' | 'json' | 'json-ietf'
    tls: boolean
    sampleInterval: number       // seconds (5, 10, 30, 60)
    sensorPaths: string[]        // OpenConfig/vendor YANG paths
}

