// ─── Topology Builder config ─────────────────────────────────────────────────

export interface BuilderNodeGroup {
    role: NodeRole
    count: number
    vendor?: string
    model?: string
    speed?: PortSpeed
    portCount?: number
    vlans?: VlanDefinition[]
}

export type BuilderLinkPattern = 'full-mesh' | 'ring' | 'dual-homed' | 'custom'

export interface BuilderLinkRule {
    sourceRole: NodeRole
    targetRole: NodeRole
    pattern: BuilderLinkPattern
    linksPerPair: number       // 1, 2, or 4 for LAG/ECMP
}

export interface BuilderIpConfig {
    mode: 'ipv4' | 'ipv6' | 'dual'
    ipv4Base: string           // e.g. '10.0.0.0/16'
    ipv6Base: string           // e.g. '2001:db8::/32'
    loopbackV4: string         // e.g. '172.16.0.0/24'
    loopbackV6: string         // e.g. 'fd00::/64'
    autoAssign: boolean
}

export interface BuilderConfig {
    name: string
    groups: BuilderNodeGroup[]
    linkRules: BuilderLinkRule[]
    ipConfig: BuilderIpConfig
    vlanTemplateId?: string
    serviceProfileId?: string
    generateConfigs: boolean
    underlayProtocol?: 'ebgp' | 'ibgp-rr' | 'ospf' | 'ospfv3' | 'isis' | 'none'
    overlayEnabled?: boolean
    spineAsnStart?: number     // default 65000
    leafAsnStart?: number      // default 65100
    vniBase?: number           // default 10000; VNI = vniBase + vlanId
    // Advanced overlay options
    irbEnabled?: boolean
    irbMode?: 'symmetric' | 'asymmetric'
    irbGatewayBase?: string    // e.g. '192.168' → 192.168.<vlanId>.1/24
    macVrfEnabled?: boolean
    oismEnabled?: boolean
    telemetryEnabled?: boolean
    telemetryConfig?: TelemetryConfig
}

