// ─── VLAN utilities ─────────────────────────────────────────────────────────

/** Parse a VLAN list string like "100,200,300-400" into sorted unique IDs */
export function parseVlanList (input: string): number[] {
    const result = new Set<number>()
    for (const part of input.split(',')) {
        const trimmed = part.trim()
        if (!trimmed) { continue }
        const rangeParts = trimmed.split('-')
        if (rangeParts.length === 2) {
            const start = Number(rangeParts[0])
            const end = Number(rangeParts[1])
            if (Number.isInteger(start) && Number.isInteger(end)
                && start >= 1 && end <= 4094 && start <= end) {
                for (let i = start; i <= end; i++) { result.add(i) }
            }
        } else {
            const v = Number(trimmed)
            if (Number.isInteger(v) && v >= 1 && v <= 4094) { result.add(v) }
        }
    }
    return [...result].sort((a, b) => a - b)
}

/** Compact a sorted array of VLAN IDs back into range notation: [100,101,102,200] → "100-102,200" */
export function compactVlanList (ids: number[]): string {
    if (!ids.length) { return '' }
    const sorted = [...new Set(ids)].sort((a, b) => a - b)
    const ranges: string[] = []
    let start = sorted[0], end = sorted[0]
    for (let i = 1; i < sorted.length; i++) {
        if (sorted[i] === end + 1) { end = sorted[i] }
        else {
            ranges.push(start === end ? `${start}` : `${start}-${end}`)
            start = end = sorted[i]
        }
    }
    ranges.push(start === end ? `${start}` : `${start}-${end}`)
    return ranges.join(',')
}

