// ═══════════════════════════════════════════════════════════════════════════════
// Inventory Management System
// ═══════════════════════════════════════════════════════════════════════════════

// ─── Software / Hardware Version Tracking ────────────────────────────────────

export interface DeviceVersion {
    osVersion?: string          // e.g. "Junos 23.4R1.10"
    firmwareVersion?: string    // e.g. "BIOS 1.3.2"
    hardwareModel?: string      // e.g. "QFX5120-48Y"
    hardwareRevision?: string   // e.g. "REV 01"
    uptime?: string             // raw uptime string from device
    cpuPercent?: number         // 0–100  (from last poll)
    memoryUsedPercent?: number  // 0–100  (from last poll)
    lastPolled?: string         // ISO timestamp of last successful poll
    pollError?: string          // last poll error message
}

// ─── Config Backup ───────────────────────────────────────────────────────────

export interface ConfigBackupEntry {
    id: string                  // uuid
    nodeId: string
    timestamp: string           // ISO
    configType: 'running' | 'startup'
    content: string             // raw config text
    hash: string                // SHA-256 of content for drift detection
    trigger: 'manual' | 'scheduled' | 'event'
}

// ─── Alarms ──────────────────────────────────────────────────────────────────

export type AlarmSeverity = 'critical' | 'major' | 'minor' | 'warning' | 'info'

export type AlarmCategory =
    'interface_down' | 'high_cpu' | 'high_memory' | 'config_drift' |
    'reachability' | 'version_mismatch' | 'vendor_alarm' | 'custom'

export interface DeviceAlarm {
    id: string                  // uuid
    nodeId: string
    severity: AlarmSeverity
    category: AlarmCategory
    message: string
    detail?: string             // raw output excerpt
    raisedAt: string            // ISO timestamp
    clearedAt?: string          // ISO timestamp when cleared (undefined = active)
    acknowledged: boolean
}

// ─── Firmware Upgrade Tracking ───────────────────────────────────────────────

export type UpgradeStage =
    'planned' | 'downloading' | 'staged' | 'upgrading' |
    'verifying' | 'completed' | 'failed' | 'rolled-back'

export interface FirmwareUpgradePlan {
    id: string                  // uuid
    nodeId: string
    currentVersion: string
    targetVersion: string
    targetImageUrl?: string     // local path or URL
    stage: UpgradeStage
    createdAt: string
    updatedAt: string
    preCheckOutput?: string
    postCheckOutput?: string
    notes?: string
}

// ─── Event-Based Actions ─────────────────────────────────────────────────────

export type EventTrigger =
    'link_down' | 'link_up' | 'config_change' | 'alarm_raised' |
    'alarm_cleared' | 'poll_complete' | 'version_change' | 'command_check'

export type EventActionType =
    'notify' | 'backup_config' | 'run_command' | 'log' | 'webhook'

export interface EventRule {
    id: string
    name: string
    enabled: boolean
    trigger: EventTrigger
    nodeFilter?: string         // glob pattern on node label, or '*' for all
    vendorFilter?: string       // vendor name or '*' for all
    action: EventActionType
    actionConfig: {
        command?: string        // for 'run_command' action
        message?: string        // for 'notify' action
        checkCommand?: string   // for 'command_check' trigger: SSH command to run on device
        checkPattern?: string   // for 'command_check' trigger: regex pattern to match output
        webhookUrl?: string     // for 'webhook' action: target URL
        webhookMethod?: string  // for 'webhook' action: HTTP method (default POST)
        webhookHeaders?: Record<string, string>  // for 'webhook' action: extra headers
    }
    createdAt: string
}

// ─── Inventory Event ─────────────────────────────────────────────────────────

export interface InventoryEvent {
    type: EventTrigger
    nodeId: string
    timestamp: string           // ISO
    detail?: string
}

// ─── Top-Level Inventory Store ───────────────────────────────────────────────

export interface InventoryStore {
    version: 1
    topologyId: string                              // links to Topology.id
    deviceVersions: Record<string, DeviceVersion>   // keyed by nodeId
    deviceInterfaces: Record<string, PollInterfaceEntry[]>  // keyed by nodeId — last-polled interface statuses
    configBackups: ConfigBackupEntry[]
    alarms: DeviceAlarm[]
    upgradePlans: FirmwareUpgradePlan[]
    eventRules: EventRule[]
    eventLog: InventoryEvent[]
    pollIntervalMs: number                          // default 300000 (5 min), 0 = disabled
    lastFullPollAt?: string                         // ISO timestamp
}

/** Stored interface status from a poll (mirrors ParsedInterfaceStatus) */
export interface PollInterfaceEntry {
    name: string
    status: 'up' | 'down' | 'admin-down' | 'unknown'
    speed?: string
    description?: string
}

/** Proposed changes from polling that can be applied to the topology node */
export interface PollSyncProposal {
    nodeId: string
    nodeLabel: string
    modelChange?: { from: string; to: string }
    portChanges: PollSyncPortChange[]
    infoFields: { label: string; value: string }[]   // read-only info (OS, uptime, etc.)
}

export interface PollSyncPortChange {
    portId: string
    portLabel: string
    field: string       // e.g. 'enabled'
    from: string        // e.g. 'true'
    to: string          // e.g. 'false'
}

// ─── Workspace (multi-tab save/load) ─────────────────────────────────────────

export interface WorkspaceTabEntry {
    topology:  Topology
    inventory: InventoryStore
}

export interface WorkspaceFile {
    version:        1
    type:           'tlink-workspace'
    savedAt:        string                  // ISO timestamp
    activeTabIndex: number                  // which tab was active when saved
    tabs:           WorkspaceTabEntry[]
}
